import { useState, useCallback } from 'react';
import type { ChangeEvent, KeyboardEvent } from 'react';
import { Field, Input, Tag, Stack, Text } from '@jinx-ui/react';

export interface TagPickerProps {
  label?: string;
  placeholder?: string;
  maxTags?: number;
  initialTags?: string[];
  onChange: (tags: string[]) => void;
}

const normalize = (raw: string) => raw.trim().replace(/\s+/g, ' ');

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags = 10,
  initialTags = [],
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = normalize(raw);
      if (!tag || tags.length >= maxTags) return;
      if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) return;
      commit([...tags, tag]);
    },
    [tags, maxTags, commit],
  );

  const removeTag = useCallback(
    (tag: string) => commit(tags.filter((t) => t !== tag)),
    [tags, commit],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const isFull = tags.length >= maxTags;

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-2)' }}>
      <Field
        label={label}
        hint={`${tags.length} из ${maxTags}`}
        state={isFull ? 'warning' : 'default'}
      >
        <Input
          value={draft}
          placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
          disabled={isFull}
          onKeyDown={handleKeyDown}
          onBlur={() => {
            addTag(draft);
            setDraft('');
          }}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setDraft(event.target.value)
          }
        />
      </Field>

      {tags.length > 0 ? (
        <Stack
          direction="row"
          wrap="wrap"
          style={{ gap: 'var(--jx-space-1)' }}
        >
          {tags.map((tag) => (
            <Tag
              key={tag.toLowerCase()}
              onRemove={() => removeTag(tag)}
              removeLabel={`Удалить тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text tone="muted" size="sm">
          Пока не выбрано ни одного тега
        </Text>
      )}
    </Stack>
  );
}

